/** REG-ARCHED1 / REG-SORTED1: llave de 20 posiciones + carga útil de 340. */
public record SobreEdoCta(int tipoReg,          // ED1-TIP-REG 9(06)
                          long numGrupo,        // ED1-NUM-GPO 9(10)
                          int numCliente,       // ED1-NUM-CTE 9(04): 0 encabezados, 9998 total grupo, 9999 total general
                          EdoCtaRecord carga)   // ED1-ARCHED1 X(340)
        implements Comparable<SobreEdoCta> {

    /** SORT ... ON ASCENDING KEY SD1-NUM-GPO SD1-NUM-CTE SD1-TIP-REG */
    private static final Comparator<SobreEdoCta> ORDEN =
            Comparator.comparingLong(SobreEdoCta::numGrupo)
                      .thenComparingInt(SobreEdoCta::numCliente)
                      .thenComparingInt(SobreEdoCta::tipoReg);

    @Override public int compareTo(SobreEdoCta o) { return ORDEN.compare(this, o); }
}

/** 88 TIP-REG-VAL: solo estos tipos pasan a ARCHEDO. */
public enum TipoRegistro {
    HEADER(0), DATOS_SUCURSAL(100000), DATOS_CLIENTE(100001), RESUMEN_CPE(700000),
    HDR_SUPERGRUPO(701000), HDR_GRUPO(701100), HDR_CLIENTE(701110), DETALLE_CUENTA(701111),
    TOTAL_CLIENTE(701119), TOTAL_GRUPO(701190), TOTAL_GENERAL(709000), TRAILER(990000);

    private final int codigo;
    TipoRegistro(int codigo) { this.codigo = codigo; }

    public static Optional<TipoRegistro> de(int codigo) {
        return Arrays.stream(values()).filter(t -> t.codigo == codigo).findFirst();
    }
}

/** 701111 REGISTRO-DET-CUENTAS. */
public record DetalleCuenta(String numClienteCta,     // 9(12) como String
                            String nombre,            // X(55)
                            String sucursal,          // 9(04)
                            String numCuenta,         // 9(12)
                            BigDecimal saldoPromedio, // 9(12)V99
                            BigDecimal tasaProducto,  // 9(02)V99
                            BigDecimal tasaAdicional, // 9(02)V99 sin signo
                            int chequesTotales, int chequesExentos,   // 9(06)
                            BigDecimal productoPeriodo,              // 9(08)V99
                            BigDecimal comision,                     // 9(08)V99, incluye IVA
                            BigDecimal productoNeto,                 // 9(08)V99 en valor absoluto
                            char signo,                              // ' ' o '-'
                            BigDecimal tasaIsr, BigDecimal saldoIsr) implements EdoCtaRecord {}

/** 701190 REGISTRO-TOT-GRUPO: agrega comisiones e IVA a 10 y 15 por ciento. */
public record TotalGrupo(BigDecimal saldoPromedio,     // 9(12)V99
                         int chequesTotales, int chequesExentos,
                         BigDecimal productoPeriodo, BigDecimal comision,
                         BigDecimal productoNeto, char signo,
                         BigDecimal saldoIsr,
                         BigDecimal comision10, BigDecimal iva10,     // 9(08)V99
                         BigDecimal comision15, BigDecimal iva15) implements EdoCtaRecord {

    /** Los campos 9(08)V99 aceptan hasta 99,999,999.99; COBOL pierde los dígitos altos sin aviso. */
    static BigDecimal campo8v2(BigDecimal v) {
        BigDecimal abs = v.abs().setScale(2, RoundingMode.DOWN);
        if (abs.compareTo(new BigDecimal("99999999.99")) > 0) throw new CampoDesbordadoException(v);
        return abs;
    }
}

@Configuration
public class EdoCtaCpeJobConfig {

    /** 000-CONTROL-PROGR: si B02-NUM-CSI no es el CSI de CPE, cierra la base y termina sin archivos. */
    @Bean
    Job edoCtaCpe(JobRepository repo, Step validaVersion, Step generaArched1, Step clasificaArchedo,
                  CsiCpeDecider csi) {
        return new JobBuilder("S500P335", repo)
                .start(validaVersion)
                .next(csi).on("NO_APLICA").end()               // ELSE PERFORM 330-CIERRA-BASE
                .from(csi).on("CPE").to(generaArched1)         // 200-GENERA-EDOCTA UNTIL EOF-B39 + 300-TERMINA
                .next(clasificaArchedo)                         // 400-CLASIFICA-EDOCTA
                .end()
                .build();
    }
}

@Component
@RequiredArgsConstructor
class CsiCpeDecider implements JobExecutionDecider {
    private final ControlCaptacionRepository b02;   // OPEN INQUIRY: solo lectura
    private final P335Properties props;             // p335.csi-cpe: 10

    @Override
    public FlowExecutionStatus decide(JobExecution je, StepExecution se) {
        return b02.findCsi() == props.csiCpe() ? new FlowExecutionStatus("CPE")
                                               : new FlowExecutionStatus("NO_APLICA");
    }
}

/** 122-OBTEN-B02CONTROL + 132-ESTABLECE-FECHAS. */
public record PeriodoEdoCta(LocalDate inicio, LocalDate fin) {

    private static final DateTimeFormatter ETIQUETA = DateTimeFormatter.ofPattern("yyMMdd");

    /** B02-FECHA-LINEA viene como AAAAMMDD (9(08)); el estado de cuenta es del mes anterior completo. */
    public static PeriodoEdoCta mesAnterior(LocalDate fechaLinea) {
        YearMonth mes = YearMonth.from(fechaLinea).minusMonths(1);
        return new PeriodoEdoCta(mes.atDay(1), mes.atEndOfMonth());
    }

    /** WS-ETIQ-FECHA-EDOCTA es 9(06): el MOVE desde 9(08) deja AAMMDD. */
    public String sufijoArchivo() { return fin.format(ETIQUETA); }
}

