@Component
@StepScope
public class CorteGrupoProcessor implements ItemProcessor<CuentaCpe, List<SobreEdoCta>> {

    private Long grupoAnt;                    // WS-GPO-ANT
    private Integer subgrupoAnt;              // WS-SGP-ANT
    private int cuentasOkGrupo, cuentasOkSubgrupo;   // WS-CTAS-STAT-OKGP / OKSG
    private final Acumuladores acum = new Acumuladores();   // WKS-ACUM-ARCHED1

    /** 200-GENERA-EDOCTA: lectura de B39 por el set B39SXGPOSBGMDA (grupo, subgrupo, modalidad). */
    @Override
    public List<SobreEdoCta> process(CuentaCpe c) {
        List<SobreEdoCta> salida = new ArrayList<>();
        if (grupoAnt == null) { grupoAnt = c.grupo(); subgrupoAnt = c.subgrupo(); }

        if (c.grupo() != grupoAnt) {
            if (cuentasOkGrupo > 0) {                         // un grupo sin cuentas vigentes no se reporta
                cuentasOkGrupo = cuentasOkSubgrupo = 0;
                salida.addAll(cierraGrupo(grupoAnt, subgrupoAnt));   // 205-CAMBIO-GRUPO
            }
        } else if (c.subgrupo() != subgrupoAnt && cuentasOkSubgrupo > 0) {
            cuentasOkSubgrupo = 0;
            salida.addAll(cierraSubgrupo(grupoAnt, subgrupoAnt));    // 207-CAMBIO-SUBGPO
        }
        grupoAnt = c.grupo();
        subgrupoAnt = c.subgrupo();
        if (c.status() == 0 || c.status() == 1) {             // solo cuentas vigentes
            cuentasOkGrupo++; cuentasOkSubgrupo++;
            salida.add(detalle(c));                           // 250-GRABA-POR-CTA
        }
        return salida;
    }
    // 300-TERMINA: un StepExecutionListener.afterStep cierra el último grupo y escribe el trailer.
}

@Component
public class DetalleCuentaMapper {

    /** 250-GRABA-POR-CTA. */
    public DetalleCuenta mapea(CuentaCpe b39, int tipoPersonaPago, Acumuladores acum) {
        var mda = Mda.parte(b39.numMda());           // WKS-MDA-R: sucursal 9(04) + cuenta 9(08)

        // INC00318628663: para tipo de persona 4 la tasa adicional es la bruta del 152
        BigDecimal tasaAdic = (tipoPersonaPago == 4)
                ? b39.tasaBruta152()
                : b39.tasaNeta500().subtract(b39.tasaNeta152());
        tasaAdic = tasaAdic.abs().setScale(2, RoundingMode.DOWN);   // 9(02)V99 sin signo, COMPUTE sin ROUNDED

        BigDecimal producto = b39.rendPagado152().add(b39.isrRetenido152());   // rendimiento bruto
        BigDecimal comision = b39.comisionCobrada().add(b39.ivaCobrado());     // comisión con IVA
        BigDecimal neto     = b39.rendPagado152();                             // producto neto = rendimiento pagado

        acum.suma(b39.saldoPromedio(), b39.chequesGirados(), b39.chequesExentos(),
                  producto, comision, neto, b39.isrRetenido152());   // CTE, GPO y GRL a la vez

        return new DetalleCuenta(String.valueOf(b39.subgrupo()), b39.nombre(),
                mda.sucursal(), mda.cuenta(), b39.saldoPromedio(),
                b39.tasaNeta500(), tasaAdic, b39.chequesGirados(), b39.chequesExentos(),
                TotalGrupo.campo8v2(producto), TotalGrupo.campo8v2(comision), TotalGrupo.campo8v2(neto),
                neto.signum() < 0 ? '-' : ' ',
                b39.tasaIsr152(), TotalGrupo.campo8v2(b39.isrRetenido152()));
    }
}

