@Component
@RequiredArgsConstructor
public class RegistrosGrupo {

    private final P335Properties props;

    /** 100000 REGISTRO-DATOS-SEL: igual para todos los grupos. */
    SobreEdoCta datosSucursal(long grupo) {
        var s = props.sucursalCorporativa();
        return new SobreEdoCta(100000, grupo, 0, new DatosSucursal(s.numero(), s.domicilio(), s.nombre(),
                s.colonia(), s.poblacion(), s.estado(), s.codigoPostal()));
    }

    /** 700000: INC00318628663, persona tipo 2 cuyo último pago fue de tipo 4 usa la tasa bruta. */
    BigDecimal tasaGrupo(Grupo b37, long grupoActual, int subgrupoActual, int tipoPersonaPagoAnt) {
        boolean mismoGrupo = b37.grupo() == grupoActual && subgrupoActual > 0;
        if (mismoGrupo && b37.tipoPersona() == 2 && tipoPersonaPagoAnt == 4) {
            return b37.tasaBrutaGrupo();
        }
        return b37.tasaNetaGrupo();
    }
}

/** 701190 y 709000: totales del grupo; los importes fiscales vienen ya calculados en B37. */
List<SobreEdoCta> totales(Grupo b37, Acumuladores.Nivel gpo, Acumuladores acum) {
    char signo = gpo.productoNeto().signum() < 0 ? '-' : ' ';
    var total = new TotalGrupo(gpo.saldoPromedio(), gpo.cheques(), gpo.exentos(),
            TotalGrupo.campo8v2(gpo.productos()), TotalGrupo.campo8v2(gpo.comisiones()),
            TotalGrupo.campo8v2(gpo.productoNeto()), signo,
            b37.isrRetenido(),                  // del grupo, no la suma de B39
            b37.comision10(), b37.iva10(),
            b37.comision15(), b37.iva15());
    acum.sumaTasas(b37.comision10(), b37.iva10(), b37.comision15(), b37.iva15());   // WKS-*-GIR-10P/15P

    return List.of(
        new SobreEdoCta(701190, b37.grupo(), 9998, total),                         // al final del grupo
        new SobreEdoCta(709000, b37.grupo(), 9999, TotalGeneral.espejoDe(total))); // mismo contenido
}

@Bean
Step clasificaArchedo(JobRepository repo, PlatformTransactionManager tx,
                      ItemReader<SobreEdoCta> arched1Ordenado,   // ARCHED1 ordenado con SobreEdoCta.compareTo
                      ClassifierCompositeItemWriter<SobreEdoCta> archedo) {
    return new StepBuilder("clasificaArchedo", repo)
            .<SobreEdoCta, SobreEdoCta>chunk(100, tx)             // BLOCK CONTAINS 100 RECORDS
            .reader(arched1Ordenado)
            .processor(s -> TipoRegistro.de(s.carga().tipoReg())  // RS1-TIP-REG2: tipo dentro de la carga
                                        .map(t -> s).orElse(null)) // TIP-REG-VAL: otros tipos se descartan
            .writer(archedo)
            .build();
}

/** Cada tipo se formatea con su layout; ARCHEDO recibe solo la carga útil de 340 posiciones. */
@Bean
ClassifierCompositeItemWriter<SobreEdoCta> archedo(Map<TipoRegistro, FlatFileItemWriter<SobreEdoCta>> porTipo) {
    var w = new ClassifierCompositeItemWriter<SobreEdoCta>();
    w.setClassifier(s -> porTipo.get(TipoRegistro.de(s.carga().tipoReg()).orElseThrow()));
    return w;
}
